func checkShipcheckCommandTree(root *cobra.Command) shipcheckCheck {
	check := shipcheckCheck{Name: "command_tree", Passed: true}
	for _, path := range requiredShipcheckCommandPaths() {
		if !shipcheckCommandPathExists(root, path) {
			check.Passed = false
			check.Note = "missing required command path(s)"
			check.Evidence = append(check.Evidence, "missing: "+path)
			continue
		}
		check.Evidence = append(check.Evidence, path)
	}
	if check.Passed {
		check.Note = "required public-preview and read command paths are present"
	}
	return check
}

